/* MODULE dl07 · Bước 7 Đo lường · GA4 và dashboard đọc được
   10 bài × 7 câu. Nói ở mức khái niệm (sự kiện, phiên, người dùng, nguồn/phương tiện, chuyển đổi), không mô tả chi tiết giao diện. Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'dl07', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:dl07-01', skill:'measure', read:'6 phút', t:'Báo cáo ghi 12.000 lượt xem — vậy có bao nhiêu người đã vào web?',
  situation:'Shop gốm Bát Tràng online của Hằng chạy một tuần quảng cáo. Sếp hỏi: “Tuần này bao nhiêu người vào web?”. Báo cáo cho ba con số: 12.000 lượt xem trang, 4.000 phiên, 2.500 người dùng. Bạn đồng nghiệp định trả lời “12.000 người” vì đó là số to nhất và nghe đẹp nhất.',
  concept:{ name:'Người dùng – phiên – lượt xem',
    body:'Ba con số đo ba thứ khác nhau. <b>Người dùng</b> là số người (thực ra là số trình duyệt/thiết bị được nhận diện) đã ghé. <b>Phiên</b> là số lần ghé: một người vào sáng và tối là hai phiên. <b>Lượt xem</b> là số trang được mở trong các phiên đó. Luôn có: lượt xem ≥ phiên ≥ người dùng. Chia chúng cho nhau ra hai chỉ số hữu ích: số phiên trên mỗi người (khách có quay lại không) và số trang mỗi phiên (khách có đi sâu không). Lưu ý: cùng một người dùng điện thoại và laptop có thể bị đếm thành hai người dùng.' },
  example:'Với shop của Hằng: 4.000 phiên ÷ 2.500 người = 1,6 phiên mỗi người — khách có quay lại, hợp với hàng gốm cần cân nhắc lâu. 12.000 lượt xem ÷ 4.000 phiên = 3 trang mỗi phiên. Câu trả lời đúng cho sếp là “khoảng 2.500 người, ghé 4.000 lần, xem 12.000 trang”. Nói “12.000 người” là phóng đại gần gấp năm lần, và tuần sau khi số người thật tăng mà lượt xem giảm, cả nhóm sẽ đọc sai xu hướng.',
  takeaway:'Hỏi “bao nhiêu người” thì trả lời bằng người dùng; lượt xem là số trang, không phải số người.',
  apply:'Mở báo cáo web của một dự án bất kỳ, lấy ba con số người dùng, phiên, lượt xem. Nói trong 60 giây: mỗi người ghé mấy lần và mỗi lần xem mấy trang.',
  mistakes:['Báo cáo lượt xem trang như thể đó là số người.','Cộng người dùng của từng ngày để ra người dùng của cả tuần, trong khi một người ghé nhiều ngày bị đếm lặp.'],
  q:[
  { type:'mcq', stem:'Đoán trước: báo cáo ghi 12.000 lượt xem, 4.000 phiên, 2.500 người dùng. Con số nào trả lời câu “bao nhiêu người vào web”?',
    options:[{k:'a',t:'12.000 — vì mỗi lượt xem là một người mở trang'},{k:'b',t:'4.000 — vì mỗi phiên tương ứng với một người khách'},
             {k:'c',t:'2.500 người dùng, gần đúng nhất với số người'},{k:'d',t:'Lấy trung bình ba con số, khoảng 6.200 người đã ghé thăm'}],
    answer:'c', why:{a:'Một người có thể mở nhiều trang; lượt xem đếm trang, không đếm người.',
      b:'Một người có thể ghé nhiều lần; phiên đếm lần ghé.',
      c:'Đúng. Người dùng là thước đo gần nhất với số người, dù vẫn có sai số khi một người dùng nhiều thiết bị.',
      d:'Trung bình ba đại lượng khác bản chất không mang nghĩa gì.'} },
  { type:'mcq', stem:'Sếp muốn một con số duy nhất để theo dõi “web có thu hút thêm người mới không” qua các tuần. Bạn chọn con số nào để đặt lên đầu báo cáo?',
    options:[{k:'a',t:'Tổng lượt xem trang, vì nó to và thay đổi rõ nhất'},{k:'b',t:'Số người dùng mới trong tuần'},
             {k:'c',t:'Số trang mỗi phiên, vì nó cho biết khách thích web đến mức nào'},{k:'d',t:'Tổng số phiên, vì nó gộp được cả khách mới lẫn khách cũ'}],
    answer:'b', why:{a:'Lượt xem có thể tăng chỉ vì khách cũ xem nhiều trang hơn; nó không trả lời câu “người mới”.',
      b:'Đúng. Câu hỏi là thu hút người mới, nên thước đo phải là người dùng mới.',
      c:'Độ sâu phiên là chất lượng, không phải quy mô người mới.',
      d:'Phiên trộn lẫn khách mới và khách quay lại, nên không tách được điều sếp hỏi.'} },
  { type:'calc', stem:'Một tuần web có 9.000 lượt xem, 3.000 phiên và 2.000 người dùng. Trung bình mỗi người dùng có bao nhiêu phiên?',
    unit:'phiên', ans:1.5, tol:0.01, wrong:[[4.5,'SAI_MAU_SO'],[3,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Phiên mỗi người = số phiên ÷ số người dùng.','3.000 ÷ 2.000 = <b>1,5 phiên</b>.'] },
  { type:'calc', stem:'Cũng tuần đó (9.000 lượt xem, 3.000 phiên), trung bình mỗi phiên xem bao nhiêu trang?',
    unit:'trang', ans:3, tol:0.01, wrong:[[4.5,'SAI_MAU_SO'],[0.33,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Trang mỗi phiên = lượt xem ÷ số phiên.','9.000 ÷ 3.000 = <b>3 trang</b>.'] },
  { type:'mcq', stem:'Bạn cộng người dùng của 7 ngày (mỗi ngày khoảng 500) và báo “3.500 người trong tuần”, trong khi báo cáo cả tuần ghi 2.500. Vì sao lệch?',
    options:[{k:'a',t:'Báo cáo tuần bị lỗi, nên tin con số cộng tay vì nó chi tiết hơn'},{k:'b',t:'Một người ghé nhiều ngày bị đếm lặp khi cộng'},
             {k:'c',t:'Báo cáo tuần đã tự loại bớt khách ở nước ngoài ra khỏi tổng'},{k:'d',t:'Số theo ngày tính cả lượt xem nên luôn to hơn'}],
    answer:'b', why:{a:'Cộng tay mới là cách sai; báo cáo tuần đếm mỗi người một lần.',
      b:'Đúng. Người dùng không cộng dồn được qua các ngày vì khách quay lại bị đếm nhiều lần.',
      c:'Không có lý do gì báo cáo tuần tự loại khách nước ngoài; độ lệch đến từ đếm trùng.',
      d:'Số người dùng theo ngày vẫn đếm người, không đếm lượt xem.'} },
  { type:'mcq', stem:'Tháng này lượt xem tăng 30% nhưng người dùng giữ nguyên, số trang mỗi phiên từ 3 lên 4. Cách đọc nào hợp lý nhất?',
    options:[{k:'a',t:'Web đã thu hút thêm 30% khách mới nhờ quảng cáo tốt lên'},{k:'b',t:'Có bot tấn công, cần chặn toàn bộ lưu lượng tháng này'},
             {k:'c',t:'Vẫn chừng ấy người nhưng họ xem nhiều trang hơn mỗi lần ghé'},{k:'d',t:'Số người dùng đã bị đếm thiếu, phải nhân thêm 30% cho khớp'}],
    answer:'c', why:{a:'Người dùng không đổi, nên không có thêm khách.',
      b:'Bot là một khả năng cần kiểm tra, nhưng dữ kiện này khớp tự nhiên với việc khách đi sâu hơn.',
      c:'Đúng. Tăng lượt xem đến từ độ sâu phiên, không phải từ quy mô.',
      d:'Không có cơ sở để sửa tay dữ liệu cho khớp với con số mình muốn thấy.'} },
  { type:'mcq', stem:'Một khách xem hàng trên điện thoại buổi trưa rồi đặt mua trên laptop buổi tối. Báo cáo nhiều khả năng ghi nhận thế nào?',
    options:[{k:'a',t:'Hai người dùng khác nhau, trừ khi web nhận ra đó là cùng một người'},{k:'b',t:'Luôn là một người dùng, vì hệ thống đo nhận diện được mọi thiết bị'},
             {k:'c',t:'Một phiên duy nhất kéo dài từ trưa đến tối'},{k:'d',t:'Không ghi nhận gì vì khách đổi thiết bị giữa chừng'}],
    answer:'a', why:{a:'Đúng. Mặc định mỗi trình duyệt là một định danh; chỉ khi khách đăng nhập và web gửi mã người dùng thì mới gộp được.',
      b:'Không hệ thống nào tự nhận ra mọi thiết bị; đó là lý do số người dùng chỉ là ước lượng.',
      c:'Phiên kết thúc khi khách rời đi một thời gian; hai thiết bị càng không thể chung phiên.',
      d:'Cả hai lần ghé vẫn được ghi, chỉ là bị tách thành hai người.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:dl07-02', skill:'measure', read:'7 phút', t:'Web có hàng trăm sự kiện — nên đánh dấu cái nào là chuyển đổi?',
  situation:'Web đặt bàn của chuỗi lẩu nấm ở Hà Nội ghi lại đủ thứ: cuộn trang, bấm ảnh món, bấm nút gọi, gửi form đặt bàn, bấm chỉ đường. Bạn thực tập đánh dấu tất cả là chuyển đổi (key event). Cuối tháng báo cáo ghi 6.000 chuyển đổi, trong khi nhà hàng chỉ nhận được 300 lượt đặt bàn.',
  concept:{ name:'Sự kiện và chuyển đổi (key event)',
    body:'Trong cách đo hiện đại, mọi hành động là một <b>sự kiện</b>: xem trang, cuộn, bấm, gửi form. Chỉ một vài sự kiện gắn trực tiếp với tiền hoặc với mục tiêu kinh doanh mới nên được đánh dấu là <b>chuyển đổi</b> (key event). Quy tắc chọn: nếu con số này tăng gấp đôi mà doanh nghiệp không vui hơn, nó không phải chuyển đổi. Thường chỉ 1–3 sự kiện: mua hàng, gửi form, bấm gọi. Các sự kiện còn lại vẫn giữ để chẩn đoán, không bị xoá. Đánh dấu tràn lan làm tỉ lệ chuyển đổi đẹp giả và khiến nền tảng quảng cáo tối ưu sai hướng.' },
  example:'Chuỗi lẩu chỉ giữ hai chuyển đổi: gửi form đặt bàn và bấm gọi. Tháng sau báo cáo ghi 300 form và 150 lượt bấm gọi trên 15.000 phiên, tỉ lệ 450 ÷ 15.000 = 3%. Con số nhỏ hơn nhiều so với 6.000 trước đây nhưng khớp với sổ đặt bàn của quán. Quan trọng hơn, khi nền tảng quảng cáo được báo “chuyển đổi = đặt bàn”, nó tìm người muốn đặt bàn chứ không tìm người thích cuộn xem ảnh.',
  takeaway:'Chuyển đổi là thứ doanh nghiệp vui khi nó tăng gấp đôi; còn lại chỉ là sự kiện.',
  apply:'Liệt kê năm hành động khách làm trên một web bạn biết. Chọn đúng một hoặc hai cái làm chuyển đổi và giải thích trong 60 giây vì sao.',
  mistakes:['Đánh dấu cuộn trang hay xem video là chuyển đổi để báo cáo đẹp.','Xoá các sự kiện phụ đi thay vì giữ chúng để chẩn đoán.'],
  q:[
  { type:'mcq', stem:'Đoán trước: web ghi 6.000 “chuyển đổi” nhưng quán chỉ có 300 lượt đặt bàn. Nguyên nhân dễ xảy ra nhất?',
    options:[{k:'a',t:'Khách đặt bàn rồi huỷ nên số thật bị hụt đi nhiều'},{k:'b',t:'Nhiều sự kiện không phải đặt bàn bị tính là chuyển đổi'},
             {k:'c',t:'Công cụ đo tính sai, cần đổi sang một công cụ khác đắt tiền hơn'},{k:'d',t:'Nhân viên quán ghi sổ thiếu vì giờ cao điểm quá đông khách'}],
    answer:'b', why:{a:'Huỷ không thể giải thích mức chênh gấp 20 lần.',
      b:'Đúng. Đánh dấu cuộn, bấm ảnh… là chuyển đổi thì con số phình ra.',
      c:'Công cụ ghi đúng những gì được cài; lỗi nằm ở cách chọn chuyển đổi.',
      d:'Có thể thiếu vài lượt, nhưng không thể thiếu 5.700 lượt.'} },
  { type:'mcq', stem:'Bạn phụ trách đo cho web đặt bàn. Bạn chọn danh sách chuyển đổi nào?',
    options:[{k:'a',t:'Gửi form đặt bàn và bấm nút gọi'},{k:'b',t:'Tất cả sự kiện, để nền tảng quảng cáo có nhiều dữ liệu học nhất'},
             {k:'c',t:'Chỉ xem trang menu, vì đó là bước khách quan tâm nhiều nhất'},{k:'d',t:'Cuộn 90% trang chủ, vì cho thấy khách đọc kỹ nội dung'}],
    answer:'a', why:{a:'Đúng. Hai hành động này gắn trực tiếp với một lượt khách đến quán.',
      b:'Nền tảng học từ tín hiệu bạn cho; tín hiệu rác dạy nó tìm người thích bấm lung tung.',
      c:'Xem menu là tín hiệu quan tâm, nên giữ làm sự kiện để chẩn đoán, không phải kết quả.',
      d:'Đọc kỹ chưa phải là đặt bàn; tăng gấp đôi số cuộn không làm quán đông hơn.'} },
  { type:'calc', stem:'Sau khi sửa, tháng có 15.000 phiên, 300 lượt gửi form và 150 lượt bấm gọi (hai chuyển đổi). Tỉ lệ chuyển đổi trên phiên là bao nhiêu phần trăm?',
    unit:'%', ans:3, tol:0.05, wrong:[[2,'SAI_TINH_TOAN'],[40,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Tổng chuyển đổi = 300 + 150 = 450.','Tỉ lệ = 450 ÷ 15.000 = <b>3%</b>.'] },
  { type:'mcq', stem:'Một web bán khoá học tiếng Anh có sự kiện “xem video giới thiệu”. Nên xử lý sự kiện này thế nào?',
    options:[{k:'a',t:'Xoá đi cho báo cáo gọn, vì nó không phải chuyển đổi'},{k:'b',t:'Đánh dấu là chuyển đổi chính vì video là nội dung quan trọng nhất của web'},
             {k:'c',t:'Giữ làm sự kiện để xem người xem video có đăng ký nhiều hơn không'},{k:'d',t:'Gộp chung vào sự kiện đăng ký để tăng số liệu cho đẹp'}],
    answer:'c', why:{a:'Xoá là mất dữ liệu chẩn đoán; sự kiện phụ giúp hiểu vì sao người ta mua.',
      b:'Xem video là bước giữa; nếu đánh dấu là kết quả, quảng cáo sẽ đi tìm người thích xem video.',
      c:'Đúng. Sự kiện phụ dùng để chẩn đoán hành trình, không dùng làm mục tiêu.',
      d:'Gộp hai hành động khác nhau làm mất khả năng biết khách thật sự đăng ký hay chỉ xem.'} },
  { type:'mcq', stem:'Câu hỏi thử nào giúp quyết định nhanh một sự kiện có nên là chuyển đổi?',
    options:[{k:'a',t:'Sự kiện này có xảy ra nhiều lần mỗi ngày không, để số liệu đủ lớn'},{k:'b',t:'Sự kiện này có dễ cài đặt mà không cần nhờ lập trình viên không'},
             {k:'c',t:'Đối thủ cạnh tranh có đang đo sự kiện này hay không'},{k:'d',t:'Nếu nó tăng gấp đôi, doanh nghiệp có vui hơn không'}],
    answer:'d', why:{a:'Nhiều không có nghĩa là quan trọng; cuộn trang xảy ra rất nhiều.',
      b:'Dễ cài là chuyện kỹ thuật, không nói gì về giá trị kinh doanh.',
      c:'Mục tiêu của đối thủ khác mục tiêu của bạn.',
      d:'Đúng. Phép thử này tách được kết quả kinh doanh khỏi hoạt động bề mặt.'} },
  { type:'mcq', stem:'Shop mỹ phẩm online vừa đổi chuyển đổi từ “thêm vào giỏ” sang “mua hàng”. Tuần đầu số chuyển đổi giảm từ 900 xuống 180. Bạn báo cáo thế nào?',
    options:[{k:'a',t:'Hiệu quả giảm 80%, cần cắt ngân sách quảng cáo ngay'},{k:'b',t:'Định nghĩa đã đổi nên không so với tuần trước; lập mốc mới từ đây'},
             {k:'c',t:'Quay lại dùng “thêm vào giỏ” để số liệu không giảm'},{k:'d',t:'Nhân 180 với 5 để quy đổi về cách đếm cũ, cho sếp dễ so với các tuần trước'}],
    answer:'b', why:{a:'Số giảm do đổi cách đếm, không phải do hiệu quả kém.',
      b:'Đúng. Đổi định nghĩa là cắt chuỗi số liệu; cần ghi chú và lấy mốc mới.',
      c:'Chọn thước đo vì nó đẹp là tự lừa mình.',
      d:'Tỉ lệ từ giỏ sang mua không cố định; quy đổi như vậy là bịa số.'} },
  { type:'mcq', stem:'Vì sao đánh dấu quá nhiều chuyển đổi làm hại cả quảng cáo, không chỉ báo cáo?',
    options:[{k:'a',t:'Vì nền tảng sẽ tối ưu để tìm người làm các hành động rẻ, dễ'},{k:'b',t:'Vì mỗi chuyển đổi được đánh dấu đều bị tính thêm phí sử dụng hàng tháng'},
             {k:'c',t:'Vì web tải chậm hẳn đi khi có quá nhiều chuyển đổi được cài đặt cùng lúc'},{k:'d',t:'Vì báo cáo không cho phép đánh dấu quá ba chuyển đổi cùng lúc trên một web'}],
    answer:'a', why:{a:'Đúng. Hệ thống tối ưu theo tín hiệu; tín hiệu dễ đạt kéo quảng cáo về phía người không mua.',
      b:'Việc đánh dấu chuyển đổi không phát sinh phí theo số lượng như vậy.',
      c:'Đánh dấu là cấu hình báo cáo, không làm web nặng hơn đáng kể.',
      d:'Không nên dựa vào giới hạn giao diện; lý do thật là chất lượng tín hiệu.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:dl07-03', skill:'measure', read:'7 phút', t:'Vì sao một nửa lưu lượng hiện là “direct” dù bạn chạy quảng cáo khắp nơi?',
  situation:'Thương hiệu cà phê rang xay ở Đà Lạt chạy cùng lúc bài Facebook, tin nhắn Zalo OA và email cho khách cũ. Cuối tháng báo cáo nguồn/phương tiện cho thấy 48% phiên là “(direct) / (none)”. Sếp hỏi kênh nào đang mang khách, không ai trả lời được.',
  concept:{ name:'Nguồn/phương tiện và UTM',
    body:'Mỗi phiên được gắn <b>nguồn</b> (ai gửi khách tới: facebook, zalo, newsletter) và <b>phương tiện</b> (loại kênh: cpc, social, email). Khi đường link không mang thông tin, ví dụ bấm từ ứng dụng chat hay email, hệ thống không biết khách từ đâu và xếp vào direct. <b>UTM</b> là các tham số gắn vào cuối link (utm_source, utm_medium, utm_campaign) để tự khai nguồn. Quy tắc: mọi link bạn chủ động gửi ra đều gắn UTM, viết thường, theo một bảng quy ước chung. Không gắn UTM cho link nội bộ giữa các trang của chính web, vì nó sẽ bẻ phiên và ghi đè nguồn thật.' },
  example:'Nhóm cà phê lập bảng quy ước: utm_source = zalo / facebook / newsletter; utm_medium = social / email / paid_social; utm_campaign = tên-đợt-tháng. Tháng sau, direct giảm từ 48% xuống 15%. Hoá ra Zalo OA mang 2.400 trong 12.000 phiên, tức 20% — kênh trước đây bị giấu trong direct. Email cho khách cũ tuy chỉ 1.200 phiên nhưng có tỉ lệ mua cao nhất.',
  takeaway:'Link nào bạn chủ động gửi ra đều phải tự khai nguồn bằng UTM, theo một quy ước chung.',
  apply:'Viết một link UTM cho bài đăng Zalo tuần này: nguồn, phương tiện, tên chiến dịch. Đọc to và giải thích từng phần trong 60 giây.',
  mistakes:['Mỗi người viết UTM một kiểu (Facebook, facebook, fb) khiến một kênh bị tách thành ba dòng.','Gắn UTM vào banner nội bộ trên web, làm mất nguồn thật của phiên.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao khách bấm link trong tin Zalo lại hay bị xếp vào “direct”?',
    options:[{k:'a',t:'Vì Zalo chặn không cho web đo lường bất kỳ lượt ghé nào từ ứng dụng'},{k:'b',t:'Vì khách Zalo thường tự gõ địa chỉ web thay vì bấm link'},
             {k:'c',t:'Vì direct là tên mặc định mà hệ thống dành cho mọi ứng dụng nhắn tin'},{k:'d',t:'Vì link không mang thông tin nguồn nên hệ thống không biết khách từ đâu'}],
    answer:'d', why:{a:'Phiên vẫn được đo; chỉ là không có nhãn nguồn.',
      b:'Họ có bấm link; vấn đề là link không tự khai nguồn.',
      c:'Direct là nơi chứa phiên không rõ nguồn, không phải tên riêng cho kênh chat.',
      d:'Đúng. Không có thông tin giới thiệu, phiên rơi vào direct.'} },
  { type:'mcq', stem:'Nhóm có ba người cùng đăng link. Bạn đề xuất gì trước tiên để số liệu nguồn sạch?',
    options:[{k:'a',t:'Để mỗi người tự đặt UTM theo cách họ nhớ dễ nhất'},{k:'b',t:'Bỏ UTM đi, chỉ nhìn tổng phiên của cả web cho gọn'},
             {k:'c',t:'Một bảng quy ước UTM chung, viết thường, ai gửi link cũng tra'},{k:'d',t:'Gắn UTM cho cả các nút bấm nội bộ trên web để đo mọi thứ'}],
    answer:'c', why:{a:'Mỗi người một kiểu thì cùng một kênh bị tách thành nhiều dòng.',
      b:'Mất khả năng trả lời câu hỏi kênh nào mang khách.',
      c:'Đúng. Quy ước chung là điều kiện để số liệu cộng lại được.',
      d:'UTM trên link nội bộ ghi đè nguồn thật của phiên.'} },
  { type:'calc', stem:'Sau khi gắn UTM, tháng có 12.000 phiên, trong đó zalo / social mang 2.400 phiên. Zalo chiếm bao nhiêu phần trăm phiên?',
    unit:'%', ans:20, tol:0.1, wrong:[[500,'SAI_MAU_SO'],[2.4,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Tỉ trọng = phiên của kênh ÷ tổng phiên.','2.400 ÷ 12.000 = <b>20%</b>.'] },
  { type:'mcq', stem:'Báo cáo có ba dòng: “Facebook”, “facebook”, “fb”. Chuyện gì đã xảy ra?',
    options:[{k:'a',t:'Có ba trang Facebook khác nhau đang gửi khách tới web'},{k:'b',t:'UTM viết không thống nhất nên một nguồn bị tách làm ba'},
             {k:'c',t:'Facebook tự đổi tên nguồn theo từng loại thiết bị của khách'},{k:'d',t:'Đó là ba chiến dịch khác nhau cùng chạy song song trong tháng'}],
    answer:'b', why:{a:'Có thể, nhưng khác biệt chỉ ở chữ hoa/thường và viết tắt là dấu hiệu lỗi quy ước.',
      b:'Đúng. Giá trị UTM phân biệt chữ hoa và cách viết; phải chuẩn hoá.',
      c:'Tên nguồn trong UTM là do người gắn link đặt.',
      d:'Chiến dịch nằm ở utm_campaign, không ở utm_source.'} },
  { type:'mcq', stem:'Web có banner “Xem bộ quà Tết” trên trang chủ dẫn sang trang sản phẩm. Có nên gắn UTM cho banner này?',
    options:[{k:'a',t:'Có, để biết banner nội bộ mang bao nhiêu phiên mới'},{k:'b',t:'Có, nhưng chỉ khi đang chạy khuyến mãi lớn trong mùa Tết'},
             {k:'c',t:'Không, vì UTM chỉ dùng được cho quảng cáo trả tiền'},{k:'d',t:'Không, dùng sự kiện bấm banner; UTM sẽ ghi đè nguồn thật'}],
    answer:'d', why:{a:'Banner nội bộ không mang phiên mới; UTM ở đây làm khách từ Google bị ghi lại thành nguồn nội bộ.',
      b:'Mùa nào cũng vậy: UTM nội bộ làm hỏng dữ liệu nguồn.',
      c:'UTM dùng cho mọi link bên ngoài, kể cả email, Zalo, bài đăng miễn phí.',
      d:'Đúng. Đo tương tác nội bộ bằng sự kiện, giữ nguồn gốc phiên nguyên vẹn.'} },
  { type:'mcq', stem:'Cửa hàng in mã QR trên tờ rơi phát ở chợ. Làm sao biết bao nhiêu khách tới từ tờ rơi?',
    options:[{k:'a',t:'Cho mã QR trỏ tới link có UTM riêng cho tờ rơi'},{k:'b',t:'Đếm tăng thêm của direct trong tuần phát tờ rơi rồi ghi là từ tờ rơi'},
             {k:'c',t:'Hỏi khách khi họ thanh toán, vì web không thể đo được tờ rơi'},{k:'d',t:'Dùng tên miền chính, vì khách quét QR luôn được ghi là tờ rơi'}],
    answer:'a', why:{a:'Đúng. QR là một link như mọi link; gắn UTM thì kênh ngoại tuyến cũng tự khai nguồn.',
      b:'Direct tăng có thể vì nhiều lý do khác; đó là đoán, không phải đo.',
      c:'Hỏi khách là nguồn bổ sung tốt, nhưng web hoàn toàn đo được qua UTM.',
      d:'QR không mang nguồn nếu link không có UTM; nó sẽ rơi vào direct.'} },
  { type:'mcq', stem:'Sau khi gắn UTM đầy đủ, direct vẫn còn 15%. Cách hiểu hợp lý?',
    options:[{k:'a',t:'Vẫn còn lỗi, direct phải về 0% thì mới đo đúng'},{k:'b',t:'15% là khách cũ gõ thẳng tên web hoặc lưu dấu trang'},
             {k:'c',t:'Direct còn lại chắc chắn toàn là bot, nên loại bỏ hết'},{k:'d',t:'Phải gộp direct vào kênh lớn nhất cho báo cáo gọn gàng'}],
    answer:'b', why:{a:'Luôn có người gõ thẳng địa chỉ hay dùng dấu trang; direct không bao giờ về 0.',
      b:'Đúng. Một phần direct là thật và thường là khách đã biết thương hiệu.',
      c:'Không có căn cứ để coi toàn bộ là bot.',
      d:'Gộp vào kênh khác là gán công sai.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:dl07-04', skill:'measure', read:'6 phút', t:'Tỉ lệ thoát 70% — trang đích tệ thật hay bạn đang đọc sai số?',
  situation:'Trang đích bài blog “Cách pha cold brew tại nhà” có tỉ lệ thoát 70%. Sếp muốn viết lại cả trang. Nhưng khi xem kỹ, nhiều khách ở lại đọc 3–4 phút rồi mới đóng tab, và công thức nằm trọn trên một trang.',
  concept:{ name:'Tỉ lệ tương tác và tỉ lệ thoát',
    body:'Cách đo hiện đại coi một phiên là <b>có tương tác</b> khi khách ở lại đủ lâu (thường khoảng 10 giây), hoặc xem từ hai trang, hoặc làm một chuyển đổi. <b>Tỉ lệ tương tác</b> = phiên có tương tác ÷ tổng phiên. <b>Tỉ lệ thoát</b> là phần còn lại: phiên không có tương tác. Vì vậy khách đọc hết một bài dài rồi đi vẫn tính là có tương tác. Tỉ lệ thoát cao chỉ đáng lo khi trang cần khách đi tiếp (trang sản phẩm, trang đích quảng cáo) hoặc khi khách rời đi gần như ngay lập tức.' },
  example:'Kiểm tra lại bài cold brew theo định nghĩa mới: 5.000 phiên, 3.500 có tương tác → tỉ lệ tương tác 70%, tỉ lệ thoát chỉ 30%. Con số 70% sếp thấy là “chỉ xem một trang” theo cách hiểu cũ. Bài blog làm đúng việc của nó. Việc nên làm không phải viết lại, mà là thêm một lời mời mua hạt rang cold brew ở cuối bài để phiên có tương tác chuyển thành đơn hàng.',
  takeaway:'Trước khi sửa trang vì thoát cao, hỏi: trang này cần khách đi tiếp, hay chỉ cần họ đọc xong?',
  apply:'Chọn một trang blog và một trang sản phẩm. Nói trong 60 giây: mức thoát nào đáng lo cho từng trang và vì sao khác nhau.',
  mistakes:['So tỉ lệ thoát của trang blog với trang sản phẩm như cùng một chuẩn.','Nhầm “chỉ xem một trang” với “không tương tác”.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khách đọc một bài blog 4 phút rồi đóng tab, không bấm gì. Theo cách đo tương tác, phiên đó tính là gì?',
    options:[{k:'a',t:'Phiên thoát, vì khách chỉ xem đúng một trang rồi đi'},{k:'b',t:'Phiên lỗi, vì không có sự kiện bấm nào được ghi lại'},
             {k:'c',t:'Phiên có tương tác, vì khách ở lại đủ lâu'},{k:'d',t:'Không tính vào báo cáo vì khách không chuyển đổi gì'}],
    answer:'c', why:{a:'Đó là cách hiểu cũ; cách đo tương tác tính cả thời gian ở lại.',
      b:'Thời gian trên trang vẫn được ghi; không cần bấm.',
      c:'Đúng. Ở lại đủ lâu là một trong các điều kiện tương tác.',
      d:'Mọi phiên đều được tính; chuyển đổi chỉ là một điều kiện.'} },
  { type:'mcq', stem:'Trang đích quảng cáo “Đăng ký học thử” có tỉ lệ thoát 65%, khách ở lại trung bình 4 giây. Bạn làm gì?',
    options:[{k:'a',t:'Kiểm tra quảng cáo và trang có khớp lời hứa, tốc độ tải'},{k:'b',t:'Bỏ qua, vì thoát cao là bình thường với mọi loại trang'},
             {k:'c',t:'Viết thêm thật nhiều nội dung để khách buộc phải cuộn'},{k:'d',t:'Tăng ngân sách để bù số người bị mất ở trang'}],
    answer:'a', why:{a:'Đúng. Rời đi sau 4 giây trên trang cần khách đi tiếp là dấu hiệu lệch kỳ vọng hoặc tải chậm.',
      b:'Với trang đích cần hành động, thoát cao trong vài giây là vấn đề thật.',
      c:'Nội dung dài không cứu được một trang khách bỏ đi trước khi đọc.',
      d:'Bơm thêm tiền vào cái xô thủng chỉ làm mất thêm tiền.'} },
  { type:'calc', stem:'Bài blog có 5.000 phiên, 3.500 phiên có tương tác. Tỉ lệ thoát là bao nhiêu phần trăm?',
    unit:'%', ans:30, tol:0.1, wrong:[[70,'SAI_TINH_TOAN'],[42.9,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Tỉ lệ tương tác = 3.500 ÷ 5.000 = 70%.','Tỉ lệ thoát = 100% − 70% = <b>30%</b>.'] },
  { type:'mcq', stem:'Trang blog thoát 40%, trang giỏ hàng thoát 40%. Nhận định nào đúng?',
    options:[{k:'a',t:'Hai trang tốt như nhau vì có cùng một tỉ lệ thoát'},{k:'b',t:'Trang blog đáng lo hơn vì bài blog phải giữ khách lâu hơn'},
             {k:'c',t:'Cả hai đều cần viết lại ngay vì trên 30% là quá cao'},{k:'d',t:'Giỏ hàng đáng lo hơn nhiều vì ở đó khách lẽ ra phải đi tiếp'}],
    answer:'d', why:{a:'Cùng con số, nhưng kỳ vọng của hai trang khác hẳn nhau.',
      b:'Blog vốn có thể trọn vẹn trong một trang.',
      c:'Không có ngưỡng chung cho mọi trang.',
      d:'Đúng. Trang giỏ tồn tại để khách đi tiếp tới thanh toán.'} },
  { type:'mcq', stem:'Một bạn báo cáo: “Tỉ lệ tương tác tăng từ 55% lên 80% sau khi đổi cách đếm”. Câu hỏi đầu tiên nên đặt?',
    options:[{k:'a',t:'Nội dung web đã cải thiện nhiều thế nào trong tháng này'},{k:'b',t:'Có nên đặt mục tiêu 90% cho quý sau không'},
             {k:'c',t:'Định nghĩa phiên có tương tác đã đổi thế nào'},{k:'d',t:'Có nên khen thưởng nhóm nội dung vì con số tăng'}],
    answer:'c', why:{a:'Chưa thể nói nội dung tốt lên khi thước đo vừa đổi.',
      b:'Đặt mục tiêu trên một chuỗi số bị gãy là vô nghĩa.',
      c:'Đúng. Đổi định nghĩa có thể tự đẩy con số lên mà không có gì thật sự thay đổi.',
      d:'Khen thưởng vì thay đổi cách đếm là thưởng sai người.'} },
  { type:'mcq', stem:'Thời gian tương tác trung bình của trang sản phẩm là 8 phút — cao bất thường so với các trang khác. Khả năng nào đáng kiểm tra đầu tiên?',
    options:[{k:'a',t:'Khách để tab mở rồi làm việc khác, kéo trung bình lên'},{k:'b',t:'Sản phẩm quá hấp dẫn nên khách đọc rất kỹ từng dòng'},
             {k:'c',t:'Trang tải quá nhanh nên khách xem được nhiều hơn'},{k:'d',t:'Đó là dấu hiệu chắc chắn khách sắp đặt hàng số lượng lớn'}],
    answer:'a', why:{a:'Đúng. Trung bình dễ bị vài giá trị cực lớn kéo lệch; nên xem thêm trung vị hoặc phân bố.',
      b:'Có thể, nhưng 8 phút cho một trang sản phẩm là bất thường, cần loại khả năng dữ liệu lệch trước.',
      c:'Tải nhanh không làm khách ở lâu hơn gấp nhiều lần.',
      d:'Thời gian dài không phải bằng chứng ý định mua.'} },
  { type:'mcq', stem:'Trang “Liên hệ” có tỉ lệ thoát 85%: khách vào xem số điện thoại rồi gọi. Nên xử lý thế nào?',
    options:[{k:'a',t:'Thêm nội dung giới thiệu để giữ khách ở lại lâu hơn trên trang'},{k:'b',t:'Đo sự kiện bấm số điện thoại để thấy trang đang làm tốt'},
             {k:'c',t:'Chuyển số điện thoại sang trang khác để khách phải đi tiếp'},{k:'d',t:'Xoá trang Liên hệ vì nó làm tỉ lệ thoát toàn web tăng lên'}],
    answer:'b', why:{a:'Khách vào để lấy số rồi gọi; giữ họ lâu hơn là làm khó họ.',
      b:'Đúng. Khi trang hoàn thành việc bằng một hành động, đo hành động đó thay vì lo chuyện thoát.',
      c:'Bắt khách đi thêm bước để làm đẹp số liệu là làm hại trải nghiệm.',
      d:'Trang đang giúp khách liên hệ; xoá nó chỉ để số đẹp là bỏ gốc lấy ngọn.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:dl07-05', skill:'measure', read:'6 phút', t:'Lưu lượng tăng vọt đêm qua — khách thật hay chính nhân viên và bot?',
  situation:'Web của một công ty nội thất ở Bình Dương bỗng tăng 40% phiên trong tuần ra mắt bộ sưu tập mới. Nhưng đơn hàng không tăng. Nhóm nhận ra 20 nhân viên mở web cả ngày để kiểm tra trang, và có một lượng phiên lạ từ một thành phố nước ngoài, mỗi phiên dưới 1 giây.',
  concept:{ name:'Lọc lưu lượng nội bộ và bot',
    body:'Dữ liệu web lẫn hai loại “khách giả”. <b>Lưu lượng nội bộ</b>: nhân viên, đối tác thiết kế, nhóm kiểm thử — thường lọc theo địa chỉ IP văn phòng hoặc đánh dấu thiết bị nội bộ. <b>Bot và spam</b>: công cụ tự động quét web; phần lớn bot đã biết được lọc sẵn, nhưng vẫn lọt nhiều loại. Dấu hiệu bot: phiên cực ngắn, tỉ lệ tương tác gần 0, dồn từ một nơi hay một giờ lạ, nguồn lạ. Nguyên tắc: lọc từ hôm nay trở đi và ghi chú ngày bắt đầu lọc; không sửa tay số cũ. Luôn giữ một bản dữ liệu thô chưa lọc để đối chiếu.' },
  example:'Nhóm nội thất tách số: tuần ra mắt 14.000 phiên, trong đó 2.800 từ IP văn phòng và 1.400 phiên dưới 1 giây từ một nguồn lạ. Khách thật còn 14.000 − 2.800 − 1.400 = 9.800 phiên. Tuần trước là 10.000 phiên (khi đó nội bộ ít). Vậy khách thật gần như đứng yên — khớp với chuyện đơn không tăng. Bài học: bộ sưu tập mới chưa kéo thêm khách, cần xem lại kênh phân phối nội dung ra mắt.',
  takeaway:'Trước khi ăn mừng lưu lượng tăng, trừ nhân viên và bot rồi mới đọc.',
  apply:'Nghĩ về web công ty bạn: ai trong nội bộ vào web thường xuyên? Nói trong 60 giây cách bạn sẽ tách họ ra khỏi số liệu.',
  mistakes:['Lọc xong rồi sửa tay số tháng cũ cho khớp.','Chỉ lọc bot mà quên nhân viên, đội agency và nhóm kiểm thử.'],
  q:[
  { type:'mcq', stem:'Đoán trước: phiên tăng 40% trong tuần ra mắt nhưng đơn không đổi. Nghi vấn đầu tiên nên kiểm tra?',
    options:[{k:'a',t:'Giá sản phẩm quá cao nên khách xem nhiều mà không mua'},{k:'b',t:'Web bị lỗi thanh toán khiến khách không đặt hàng được'},
             {k:'c',t:'Khách đang so sánh giá với đối thủ nên chưa quyết định mua'},{k:'d',t:'Phần tăng là nhân viên và bot, không phải khách thật'}],
    answer:'d', why:{a:'Có thể, nhưng trước khi giải thích hành vi khách, phải chắc đó là khách.',
      b:'Lỗi thanh toán đáng kiểm tra, nhưng tuần ra mắt là lúc nhân viên vào web nhiều nhất.',
      c:'Giải thích hành vi khi chưa làm sạch dữ liệu là đọc sai từ gốc.',
      d:'Đúng. Làm sạch dữ liệu là bước đầu trước mọi giải thích.'} },
  { type:'mcq', stem:'Bạn vừa thiết lập lọc IP văn phòng. Sếp yêu cầu “sửa luôn số ba tháng trước cho sạch”. Bạn làm gì?',
    options:[{k:'a',t:'Trừ tay một tỉ lệ ước chừng khỏi số của từng tháng cũ'},{k:'b',t:'Ghi chú ngày bắt đầu lọc; so sánh cũ và mới có cảnh báo'},
             {k:'c',t:'Xoá hết số cũ để dashboard chỉ còn dữ liệu sạch'},{k:'d',t:'Tắt lọc để chuỗi số liệu nhất quán như trước đây'}],
    answer:'b', why:{a:'Trừ theo ước chừng là bịa số; không ai kiểm chứng được.',
      b:'Đúng. Bộ lọc áp từ khi bật; minh bạch về mốc thay đổi quan trọng hơn chuỗi số đẹp.',
      c:'Xoá dữ liệu cũ là mất khả năng đối chiếu.',
      d:'Nhất quán nhưng sai thì vẫn là sai.'} },
  { type:'calc', stem:'Tuần ra mắt có 14.000 phiên, trong đó 2.800 phiên từ IP văn phòng và 1.400 phiên bot. Còn bao nhiêu phiên khách thật?',
    unit:'phiên', ans:9800, tol:1, wrong:[[11200,'SAI_TINH_TOAN'],[12600,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Khách thật = tổng − nội bộ − bot.','14.000 − 2.800 − 1.400 = <b>9.800 phiên</b>.'] },
  { type:'mcq', stem:'Dấu hiệu nào gợi ý mạnh nhất rằng một nguồn lưu lượng là bot?',
    options:[{k:'a',t:'Phiên dưới 1 giây, tương tác gần 0, dồn vào một giờ'},{k:'b',t:'Phiên đến từ điện thoại vào buổi tối sau giờ làm việc'},
             {k:'c',t:'Khách xem nhiều trang sản phẩm trong một phiên dài'},{k:'d',t:'Nguồn là một trang báo lớn vừa đăng bài nói về thương hiệu'}],
    answer:'a', why:{a:'Đúng. Hành vi máy móc: cực ngắn, không tương tác, dồn đồng loạt.',
      b:'Đó là hành vi rất bình thường của khách thật.',
      c:'Xem sâu là dấu hiệu khách thật quan tâm.',
      d:'Tăng đột ngột từ báo chí là khách thật tò mò.'} },
  { type:'mcq', stem:'Công ty thuê agency làm web, đội agency vào web hằng ngày từ văn phòng của họ. Nên xử lý thế nào?',
    options:[{k:'a',t:'Không cần lọc vì agency không phải là nhân viên công ty'},{k:'b',t:'Yêu cầu agency ngừng vào web để số liệu được sạch'},
             {k:'c',t:'Chỉ lọc agency vào các tuần có chiến dịch lớn'},{k:'d',t:'Thêm IP của agency vào danh sách lưu lượng nội bộ'}],
    answer:'d', why:{a:'Nội bộ là bất kỳ ai vào web vì công việc, không phải vì mua.',
      b:'Agency cần vào web để làm việc; lọc là đủ.',
      c:'Lọc lúc có lúc không làm chuỗi số liệu không so được.',
      d:'Đúng. Mọi người vào web vì công việc đều nên được lọc.'} },
  { type:'mcq', stem:'Sau khi lọc, tỉ lệ chuyển đổi toàn web tăng từ 1,2% lên 1,6%. Cách diễn giải đúng?',
    options:[{k:'a',t:'Web đã bán tốt hơn 33% nhờ bộ sưu tập mới ra mắt'},{k:'b',t:'Bộ lọc bị lỗi vì tỉ lệ chuyển đổi không thể tăng khi phiên giảm'},
             {k:'c',t:'Mẫu số bớt phiên giả nên tỉ lệ phản ánh sát khách thật hơn'},{k:'d',t:'Nên tắt lọc vì con số mới sẽ làm sếp kỳ vọng quá cao'}],
    answer:'c', why:{a:'Số đơn không đổi; chỉ mẫu số thay đổi.',
      b:'Bớt phiên giả thì tỉ lệ tăng là điều hoàn toàn hợp lý.',
      c:'Đúng. Tỉ lệ đổi vì cách đo sạch hơn, không phải vì bán được hơn.',
      d:'Giải pháp là giải thích rõ, không phải giữ số sai.'} },
  { type:'mcq', stem:'Vì sao nên giữ một bản dữ liệu thô chưa lọc song song?',
    options:[{k:'a',t:'Để báo cáo cho sếp con số lớn hơn khi cần thiết'},{k:'b',t:'Để kiểm tra bộ lọc có loại nhầm khách thật hay không'},
             {k:'c',t:'Vì bắt buộc phải giữ bản thô thì hệ thống mới chạy'},{k:'d',t:'Để cộng dồn hai bản với nhau cho tổng phiên chính xác hơn'}],
    answer:'b', why:{a:'Dùng số thô để báo cáo đẹp là đi ngược mục đích lọc.',
      b:'Đúng. Bộ lọc có thể sai; bản thô là chỗ đối chiếu.',
      c:'Đó là khuyến nghị thực hành, không phải điều kiện kỹ thuật.',
      d:'Cộng hai bản là đếm trùng.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:dl07-06', skill:'measure', read:'7 phút', t:'Dashboard 30 chỉ số, sếp vẫn hỏi “tuần này ổn không” — thiếu gì?',
  situation:'Chị Mai quản lý marketing cho chuỗi trà sữa 15 cửa hàng ở TP.HCM. Dashboard hiện có 30 ô số: phiên, lượt xem, cuộn trang, thời gian, thiết bị, trình duyệt… Mỗi sáng thứ Hai, giám đốc mở ra, cuộn hai lần rồi nhắn hỏi: “Tuần này ổn không em?”.',
  concept:{ name:'Dashboard một màn hình: 5–7 chỉ số',
    body:'Một dashboard tốt trả lời được một câu hỏi trong 10 giây. Cách chọn: bắt đầu từ mục tiêu kinh doanh, đi ngược thành một chuỗi ngắn. Thường gồm: <b>một chỉ số kết quả</b> (doanh thu hoặc đơn), <b>2–3 chỉ số dẫn dắt</b> (phiên, tỉ lệ chuyển đổi, giá trị đơn), <b>1–2 chỉ số sức khoẻ</b> (chi phí mỗi đơn, tỉ lệ khách quay lại). Mỗi chỉ số phải có so sánh (kỳ trước, mục tiêu) và mỗi chỉ số phải dẫn tới một hành động khi nó xấu đi. Chỉ số không ai hành động theo thì chuyển xuống trang chi tiết.' },
  example:'Chị Mai giữ 6 ô: đơn online, doanh thu, phiên, tỉ lệ chuyển đổi, giá trị đơn trung bình, chi phí quảng cáo mỗi đơn. Doanh thu = phiên × tỉ lệ chuyển đổi × giá trị đơn: 20.000 × 2% × 60.000 đ = 24 triệu đồng. Tuần này đơn giảm; nhìn chuỗi thấy phiên vẫn vậy, tỉ lệ chuyển đổi rơi — vậy vấn đề nằm ở trang web hoặc ưu đãi, không phải ở quảng cáo. Giám đốc đọc được trong một phút.',
  takeaway:'Mỗi ô trên dashboard phải trả lời được: nếu nó xấu đi, ai làm gì?',
  apply:'Chọn 6 chỉ số cho dashboard của một shop bạn biết. Nói trong 60 giây vì sao giữ mỗi ô và bỏ những ô khác.',
  mistakes:['Đưa mọi chỉ số có sẵn lên cho “đầy đủ”.','Chỉ có con số, không có so sánh với kỳ trước hay mục tiêu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao dashboard 30 chỉ số vẫn không trả lời được câu “tuần này ổn không”?',
    options:[{k:'a',t:'Vì 30 chỉ số vẫn còn thiếu, cần thêm dữ liệu từ các cửa hàng'},{k:'b',t:'Vì giám đốc không đủ chuyên môn đọc các chỉ số kỹ thuật'},
             {k:'c',t:'Vì không có thứ tự ưu tiên và không có so sánh'},{k:'d',t:'Vì dashboard chưa có màu sắc đủ bắt mắt để thu hút người xem'}],
    answer:'c', why:{a:'Thêm số chỉ làm vấn đề nặng hơn.',
      b:'Dashboard phải được thiết kế cho người đọc, không bắt người đọc thích nghi.',
      c:'Đúng. Không có chỉ số chính và mốc so sánh thì không ai biết “ổn” là gì.',
      d:'Màu sắc không thay được cấu trúc.'} },
  { type:'mcq', stem:'Bạn được giao làm lại dashboard cho giám đốc chuỗi trà sữa. Bạn chọn giữ bộ chỉ số nào?',
    options:[{k:'a',t:'Phiên, lượt xem, cuộn trang, thời gian, thiết bị, trình duyệt'},{k:'b',t:'Chỉ một ô doanh thu thật to cho dễ nhìn'},
             {k:'c',t:'Toàn bộ 30 chỉ số, nhưng chia thành nhiều tab khác nhau cho gọn'},{k:'d',t:'Đơn, doanh thu, phiên, tỉ lệ chuyển đổi, giá trị đơn, chi phí mỗi đơn'}],
    answer:'d', why:{a:'Toàn chỉ số hoạt động web, không chạm tới kết quả kinh doanh.',
      b:'Một ô cho biết ổn hay không, nhưng không cho biết vì sao.',
      c:'Chia tab không giảm số thứ phải đọc.',
      d:'Đúng. Một chuỗi từ kết quả tới nguyên nhân, có cả chi phí.'} },
  { type:'calc', stem:'Tuần có 20.000 phiên, tỉ lệ chuyển đổi 2%, giá trị đơn trung bình 60.000 đ. Doanh thu online là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:24, tol:0.1, wrong:[[1200,'QUEN_TI_LE_CHUYEN_DOI'],[2.4,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI','SAI_TINH_TOAN'],
    steps:['Số đơn = 20.000 × 2% = 400 đơn.','Doanh thu = 400 × 60.000 đ = 24.000.000 đ = <b>24 triệu đồng</b>.'] },
  { type:'mcq', stem:'Đơn giảm 15%, phiên không đổi, giá trị đơn không đổi. Dashboard 6 ô chỉ cho bạn nhìn vào đâu?',
    options:[{k:'a',t:'Kênh quảng cáo, vì đơn giảm là do quảng cáo kém hiệu quả đi'},{k:'b',t:'Tỉ lệ chuyển đổi: web, giá hay ưu đãi có vấn đề'},
             {k:'c',t:'Giá trị đơn, vì khách đang mua ít món hơn mỗi lần'},{k:'d',t:'Thiết bị và trình duyệt, vì có thể web lỗi trên một loại máy'}],
    answer:'b', why:{a:'Phiên không đổi nghĩa là quảng cáo vẫn đưa khách tới như cũ.',
      b:'Đúng. Theo chuỗi, chỉ còn tỉ lệ chuyển đổi thay đổi.',
      c:'Dữ kiện nói giá trị đơn không đổi.',
      d:'Có thể là một nguyên nhân, nhưng đó là bước đào sâu sau khi chuỗi chỉ ra tỉ lệ chuyển đổi.'} },
  { type:'mcq', stem:'Một đồng nghiệp muốn thêm ô “số lượt cuộn trang” vào dashboard chính. Câu hỏi nào giúp bạn quyết định?',
    options:[{k:'a',t:'Khi số này xấu đi, ai sẽ làm gì khác đi?'},{k:'b',t:'Số này có dễ lấy từ hệ thống đo lường hiện tại không?'},
             {k:'c',t:'Số này có thay đổi nhiều qua từng tuần để dashboard sinh động không?'},{k:'d',t:'Giám đốc có từng nhắc tới chỉ số này trong một cuộc họp nào chưa?'}],
    answer:'a', why:{a:'Đúng. Chỉ số không dẫn tới hành động thì thuộc trang chi tiết.',
      b:'Dễ lấy không có nghĩa là đáng đưa lên.',
      c:'Dao động nhiều thậm chí gây nhiễu cho người đọc.',
      d:'Được nhắc một lần không đủ lý do chiếm chỗ lâu dài.'} },
  { type:'mcq', stem:'Ô “Doanh thu: 24 triệu” đứng một mình. Cần thêm gì để nó đọc được?',
    options:[{k:'a',t:'Biểu tượng tiền và font chữ thật lớn, đậm'},{k:'b',t:'Chi tiết doanh thu của từng sản phẩm trong cùng ô đó'},
             {k:'c',t:'So sánh với kỳ trước hoặc với mục tiêu'},{k:'d',t:'Chú thích định nghĩa doanh thu dài ba dòng'}],
    answer:'c', why:{a:'To hơn không làm nó có nghĩa hơn.',
      b:'Nhồi chi tiết vào ô tổng làm mất tính một cái nhìn.',
      c:'Đúng. Một con số chỉ có nghĩa khi có mốc để so.',
      d:'Định nghĩa nên có nhưng đặt ở chú thích; điều thiếu chính là mốc so sánh.'} },
  { type:'mcq', stem:'Công ty bán phần mềm quản lý quán cà phê (thu phí hằng tháng) làm dashboard. Chỉ số kết quả nào hợp nhất?',
    options:[{k:'a',t:'Tổng số phiên vào trang giới thiệu phần mềm'},{k:'b',t:'Doanh thu định kỳ hằng tháng từ khách trả phí'},
             {k:'c',t:'Số lượt tải tài liệu giới thiệu sản phẩm miễn phí'},{k:'d',t:'Số người theo dõi fanpage của công ty trong tháng'}],
    answer:'b', why:{a:'Phiên là chỉ số dẫn dắt, không phải kết quả.',
      b:'Đúng. Với mô hình thu phí định kỳ, doanh thu định kỳ là kết quả gốc.',
      c:'Tải tài liệu là tín hiệu quan tâm sớm.',
      d:'Người theo dõi không trả tiền.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:dl07-07', skill:'measure', read:'6 phút', t:'Biểu đồ tròn 12 lát cho doanh thu theo tháng — chọn sai biểu đồ ở đâu?',
  situation:'Bạn Tùng làm báo cáo quý cho shop giày thể thao. Doanh thu 12 tháng được vẽ thành biểu đồ tròn 12 lát; tỉ trọng kênh bán được vẽ thành đường; so sánh 5 cửa hàng dùng biểu đồ vùng xếp chồng. Người xem nhìn mãi không ra tháng nào tăng, kênh nào lớn.',
  concept:{ name:'Chọn biểu đồ theo câu hỏi',
    body:'Mỗi câu hỏi có một dạng biểu đồ hợp nhất. <b>Xu hướng theo thời gian</b>: biểu đồ đường, trục ngang là thời gian. <b>So sánh giữa các nhóm</b>: cột hoặc thanh ngang, xếp từ lớn đến nhỏ, trục bắt đầu từ 0. <b>Tỉ trọng</b> của một tổng: thanh xếp chồng 100% hoặc tròn, nhưng chỉ khi có ít phần (tối đa khoảng 3–5). <b>Một con số quan trọng</b>: ô số lớn kèm mũi tên thay đổi. Quy tắc chung: một biểu đồ, một câu hỏi, và tiêu đề biểu đồ nói luôn kết luận, ví dụ “Doanh thu tăng đều từ tháng 6”.' },
  example:'Tùng vẽ lại: doanh thu 12 tháng thành đường — thấy rõ đỉnh tháng 11 nhờ mùa mua sắm cuối năm. Tỉ trọng kênh thành thanh 100%: sàn TMĐT 45%, web 30%, cửa hàng 25%. Năm cửa hàng thành thanh ngang xếp giảm dần: cửa hàng Quận 1 đạt 320 triệu, gấp đôi cửa hàng Thủ Đức 160 triệu. Tiêu đề mỗi biểu đồ là một câu kết luận. Buổi họp rút từ 40 phút xuống 15 phút.',
  takeaway:'Hỏi trước: xu hướng, so sánh hay tỉ trọng? Rồi mới chọn biểu đồ.',
  apply:'Lấy một báo cáo bạn đã thấy, chọn một biểu đồ. Nói trong 60 giây nó trả lời câu hỏi gì và dạng biểu đồ nào hợp hơn.',
  mistakes:['Dùng biểu đồ tròn cho quá nhiều phần hoặc cho dữ liệu thời gian.','Cắt trục cột không bắt đầu từ 0, làm chênh lệch nhỏ trông khổng lồ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: doanh thu 12 tháng nên vẽ bằng biểu đồ gì để thấy xu hướng?',
    options:[{k:'a',t:'Biểu đồ tròn 12 lát, mỗi tháng là một lát bánh riêng'},{k:'b',t:'Biểu đồ đường, trục ngang là tháng'},
             {k:'c',t:'Bảng số 12 dòng, vì bảng luôn chính xác hơn mọi biểu đồ'},{k:'d',t:'Biểu đồ vùng xếp chồng theo từng sản phẩm trong tháng'}],
    answer:'b', why:{a:'Tròn cho tỉ trọng, không cho thấy thứ tự thời gian.',
      b:'Đúng. Đường nối các điểm theo thời gian làm lộ xu hướng.',
      c:'Bảng chính xác nhưng mắt không thấy xu hướng qua 12 dòng số.',
      d:'Xếp chồng nhiều lớp làm khó đọc tổng lẫn từng phần.'} },
  { type:'mcq', stem:'Bạn cần cho giám đốc thấy cửa hàng nào bán tốt nhất trong 5 cửa hàng. Bạn chọn gì?',
    options:[{k:'a',t:'Biểu đồ đường nối 5 cửa hàng lại với nhau theo thứ tự tên'},{k:'b',t:'Biểu đồ tròn 5 lát, mỗi lát là doanh thu một cửa hàng'},
             {k:'c',t:'Biểu đồ vùng xếp chồng thể hiện doanh thu cả năm cửa hàng'},{k:'d',t:'Thanh ngang xếp giảm dần, trục bắt đầu từ 0'}],
    answer:'d', why:{a:'Đường ngụ ý một sự nối tiếp; giữa các cửa hàng không có thứ tự như vậy.',
      b:'Tròn làm khó so các lát gần bằng nhau.',
      c:'Vùng xếp chồng dành cho thời gian, không cho so nhóm.',
      d:'Đúng. Thanh xếp theo thứ tự giúp so sánh trong một cái liếc.'} },
  { type:'calc', stem:'Cửa hàng Quận 1 đạt 320 triệu, cửa hàng Thủ Đức đạt 160 triệu. Quận 1 cao hơn Thủ Đức bao nhiêu phần trăm?',
    unit:'%', ans:100, tol:0.1, wrong:[[50,'SAI_MAU_SO'],[200,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Chênh lệch = 320 − 160 = 160 triệu.','So với Thủ Đức: 160 ÷ 160 = <b>100%</b>.'] },
  { type:'mcq', stem:'Một biểu đồ cột có trục bắt đầu từ 90, cột A = 95, cột B = 100. Người xem dễ hiểu sai điều gì?',
    options:[{k:'a',t:'Tưởng B gấp đôi A, trong khi chỉ chênh khoảng 5%'},{k:'b',t:'Tưởng A lớn hơn B vì cột A đặt bên trái'},
             {k:'c',t:'Không hiểu sai gì vì con số đã ghi rõ trên đầu mỗi cột'},{k:'d',t:'Tưởng dữ liệu bị thiếu vì trục không bắt đầu từ 0'}],
    answer:'a', why:{a:'Đúng. Chiều cao cột 5 và 10 đơn vị trên trục cắt trông như gấp đôi.',
      b:'Vị trí trái phải không làm đảo thứ tự lớn nhỏ.',
      c:'Mắt đọc chiều cao trước khi đọc số; ghi số không cứu được ấn tượng sai.',
      d:'Người xem thường không để ý trục; họ tin vào hình.'} },
  { type:'mcq', stem:'Tỉ trọng doanh thu theo 3 kênh: sàn 45%, web 30%, cửa hàng 25%. Dạng nào ổn?',
    options:[{k:'a',t:'Biểu đồ đường, mỗi kênh là một điểm trên đường'},{k:'b',t:'Biểu đồ phân tán với ba chấm ở ba góc khác nhau'},
             {k:'c',t:'Thanh xếp chồng 100% hoặc tròn, vì chỉ có ba phần'},{k:'d',t:'Ba ô số riêng không ghi tổng, để người xem tự cộng'}],
    answer:'c', why:{a:'Đường cho thời gian, không cho phần của một tổng.',
      b:'Phân tán dùng cho quan hệ hai biến.',
      c:'Đúng. Ít phần, câu hỏi là tỉ trọng — đây là chỗ biểu đồ tròn hợp lệ.',
      d:'Tách rời làm mất cảm giác “phần của một tổng”.'} },
  { type:'mcq', stem:'Tiêu đề biểu đồ nào giúp người đọc nhất?',
    options:[{k:'a',t:'“Biểu đồ doanh thu theo tháng năm nay của shop”'},{k:'b',t:'“Doanh thu tăng đều từ tháng 6, đỉnh tháng 11”'},
             {k:'c',t:'“Hình 3” kèm chú thích nguồn dữ liệu ở cuối trang'},{k:'d',t:'“Doanh thu” — để người đọc tự kết luận'}],
    answer:'b', why:{a:'Mô tả biểu đồ là gì, không nói nó cho thấy gì.',
      b:'Đúng. Tiêu đề là kết luận; người bận chỉ đọc tiêu đề.',
      c:'Đánh số hình không giúp người đọc hiểu.',
      d:'Để tự kết luận thì mỗi người đọc một kiểu.'} },
  { type:'mcq', stem:'Bạn muốn cho thấy tỉ lệ chuyển đổi của web theo 52 tuần, và đánh dấu tuần có khuyến mãi. Cách nào tốt?',
    options:[{k:'a',t:'Biểu đồ đường, tô đậm hoặc ghi chú các tuần khuyến mãi'},{k:'b',t:'52 biểu đồ tròn nhỏ, mỗi tuần một biểu đồ riêng'},
             {k:'c',t:'Biểu đồ cột 52 cột, tô màu khác nhau cho mỗi tuần'},{k:'d',t:'Chỉ ghi số trung bình năm, bỏ chi tiết theo tuần'}],
    answer:'a', why:{a:'Đúng. Đường cho xu hướng; ghi chú giúp nối biến động với sự kiện.',
      b:'52 hình tròn không so được với nhau.',
      c:'52 màu khác nhau không mang thông tin nào.',
      d:'Trung bình giấu đi đúng thứ bạn muốn thấy.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:dl07-08', skill:'measure', read:'6 phút', t:'Doanh thu tháng 2 giảm 30% so với tháng 1 — đáng lo hay chỉ là Tết?',
  situation:'Shop đồ ăn vặt online ở Hà Nội thấy dashboard đỏ rực: doanh thu tháng 2 giảm 30% so với tháng 1. Nhân viên mới đề xuất tăng ngân sách quảng cáo gấp đôi. Nhưng tháng 1 năm nay là tháng mua sắm trước Tết, tháng 2 là tháng sau Tết.',
  concept:{ name:'So sánh cùng kỳ trên dashboard',
    body:'So với <b>kỳ liền trước</b> (tuần trước, tháng trước) cho thấy chuyển động ngắn hạn, nhưng bị mùa vụ làm méo. So với <b>cùng kỳ năm trước</b> loại được mùa vụ: tháng 2 năm nay so với tháng 2 năm ngoái. Ở Việt Nam, Tết âm lịch rơi vào các ngày dương lịch khác nhau mỗi năm, nên cần so theo tuần tương ứng với Tết chứ không chỉ theo tháng dương lịch. Dashboard tốt hiển thị cả hai mốc cạnh nhau, kèm ghi chú sự kiện (Tết, ngày đôi, khuyến mãi lớn).' },
  example:'Shop đồ ăn vặt: tháng 2 năm nay 140 triệu, tháng 1 là 200 triệu → giảm 30%. Nhưng tháng 2 năm ngoái (cũng là tháng sau Tết) chỉ 125 triệu → năm nay tăng 12%. Kết luận ngược hẳn: shop đang tăng trưởng, cú giảm là do mùa. Không cần tăng gấp đôi ngân sách; việc cần làm là chuẩn bị hàng cho mùa cao điểm tiếp theo.',
  takeaway:'Trước khi hoảng vì số giảm, đặt nó cạnh cùng kỳ năm trước.',
  apply:'Chọn một tháng có sự kiện lớn trong ngành của bạn. Nói trong 60 giây: so với tháng trước và với cùng kỳ năm trước sẽ cho hai câu chuyện khác nhau ra sao.',
  mistakes:['Chỉ so với tháng liền trước và phản ứng với biến động mùa vụ.','So cùng tháng dương lịch khi Tết rơi vào tháng khác nhau giữa hai năm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: doanh thu tháng sau Tết giảm 30% so với tháng trước Tết. Đọc thế nào?',
    options:[{k:'a',t:'Shop đang gặp khủng hoảng, cần hành động ngay lập tức'},{k:'b',t:'Đối thủ đã cướp khách trong dịp Tết nên doanh thu sụt'},
             {k:'c',t:'Có thể do mùa; cần so với cùng kỳ năm trước'},{k:'d',t:'Quảng cáo đã hết hiệu quả, cần thay toàn bộ nội dung'}],
    answer:'c', why:{a:'Kết luận khủng hoảng khi chưa loại trừ mùa vụ là vội.',
      b:'Chưa có dữ kiện nào về đối thủ.',
      c:'Đúng. Mùa mua sắm trước Tết làm tháng 1 cao bất thường.',
      d:'Không có dữ kiện về quảng cáo; đây là suy diễn.'} },
  { type:'mcq', stem:'Bạn thiết kế lại ô doanh thu trên dashboard. Bạn chọn cách hiển thị nào?',
    options:[{k:'a',t:'Chỉ hiện thay đổi so với tháng trước cho đơn giản dễ đọc'},{k:'b',t:'Hiện cả so với kỳ trước và cùng kỳ năm trước, có ghi chú sự kiện'},
             {k:'c',t:'Chỉ hiện so với cùng kỳ năm trước, bỏ hẳn kỳ trước'},{k:'d',t:'Hiện trung bình 12 tháng gần nhất để làm mờ mọi biến động'}],
    answer:'b', why:{a:'Chỉ so tháng trước sẽ báo động giả mỗi mùa thấp điểm.',
      b:'Đúng. Hai mốc cạnh nhau cho cả chuyển động ngắn hạn lẫn xu hướng đã loại mùa.',
      c:'Mất tín hiệu ngắn hạn, ví dụ một sự cố tuần này.',
      d:'Làm mờ biến động cũng làm mờ vấn đề thật.'} },
  { type:'calc', stem:'Tháng 2 năm nay doanh thu 140 triệu, tháng 2 năm ngoái 125 triệu. Tăng trưởng so với cùng kỳ là bao nhiêu phần trăm?',
    unit:'%', ans:12, tol:0.1, wrong:[[10.7,'SAI_MAU_SO'],[15,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Chênh lệch = 140 − 125 = 15 triệu.','Tăng trưởng = 15 ÷ 125 = <b>12%</b> (chia cho năm ngoái, không chia cho năm nay).'] },
  { type:'mcq', stem:'Năm ngoái Tết rơi vào cuối tháng 1, năm nay rơi vào giữa tháng 2. So tháng 2 với tháng 2 có vấn đề gì?',
    options:[{k:'a',t:'Không có vấn đề, cùng tháng dương lịch là đủ để so sánh công bằng'},{k:'b',t:'Chỉ cần nhân thêm hệ số lạm phát là so được'},
             {k:'c',t:'Chỉ cần so số ngày trong tháng là đã đủ công bằng'},{k:'d',t:'Hai tháng ở vị trí khác nhau so với Tết nên cần so theo tuần tương ứng'}],
    answer:'d', why:{a:'Tháng 2 năm nay có Tết, tháng 2 năm ngoái là sau Tết — hai hoàn cảnh khác nhau.',
      b:'Lạm phát không phải yếu tố chính ở đây.',
      c:'Số ngày không phải khác biệt lớn nhất; lệch Tết mới là.',
      d:'Đúng. Căn theo mốc Tết mới là so sánh công bằng.'} },
  { type:'mcq', stem:'Một cửa hàng mới mở được 8 tháng. Họ nên làm gì khi chưa có cùng kỳ năm trước?',
    options:[{k:'a',t:'Dùng kỳ trước kèm ghi chú mùa, và mục tiêu đã đặt'},{k:'b',t:'Mượn số của một đối thủ lớn trong ngành để làm cùng kỳ'},
             {k:'c',t:'Không cần so sánh gì cho đến khi đủ một năm dữ liệu'},{k:'d',t:'Tự ước tính số năm ngoái bằng cách lấy trung bình các tháng hiện có'}],
    answer:'a', why:{a:'Đúng. Khi thiếu dữ liệu, dùng mốc có thật và ghi chú rõ bối cảnh.',
      b:'Quy mô và khách của đối thủ khác bạn.',
      c:'Không so sánh thì không đọc được số.',
      d:'Tự ước tính số quá khứ là tạo dữ liệu giả.'} },
  { type:'mcq', stem:'Tuần ngày đôi 11/11 doanh thu tăng 80% so với tuần trước. Ghi chú nào nên có trên dashboard?',
    options:[{k:'a',t:'Không cần ghi chú, con số tự nói lên thành công của nhóm'},{k:'b',t:'Ghi “kỷ lục mới” để động viên cả nhóm marketing'},
             {k:'c',t:'Ghi “tuần 11/11 — so với tuần 11/11 năm trước”'},{k:'d',t:'Ghi mục tiêu tuần sau cũng tăng 80% để giữ nhịp'}],
    answer:'c', why:{a:'Không ghi chú, tuần sau giảm mạnh sẽ bị đọc là sự cố.',
      b:'Ăn mừng không giúp đọc số đúng.',
      c:'Đúng. Ghi sự kiện và mốc so sánh phù hợp để người đọc không nhầm.',
      d:'Mục tiêu dựa trên tuần đặc biệt là mục tiêu phi thực tế.'} },
  { type:'mcq', stem:'So với cùng kỳ, doanh thu tăng 12%, nhưng chi tiêu quảng cáo tăng 50%. Đọc thế nào?',
    options:[{k:'a',t:'Tốt: doanh thu tăng là đủ, chi phí không quan trọng'},{k:'b',t:'Chi phí tăng nhanh hơn doanh thu; cần xem lãi'},
             {k:'c',t:'Quảng cáo tăng 50% nên doanh thu cũng tăng 50%'},{k:'d',t:'Nên giảm quảng cáo về 0 để tiết kiệm tối đa'}],
    answer:'b', why:{a:'Tăng doanh thu bằng cách đốt nhiều tiền hơn có thể làm giảm lãi.',
      b:'Đúng. So cùng kỳ phải nhìn cả chi phí, không chỉ doanh thu.',
      c:'Dữ kiện cho thấy doanh thu chỉ tăng 12%.',
      d:'Nhảy sang cực đoan; cần phân tích hiệu quả từng kênh trước.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:dl07-09', skill:'measure', read:'7 phút', t:'Đơn hàng về 0 suốt 6 tiếng mà không ai biết — cần cảnh báo thế nào?',
  situation:'Thứ Bảy, web bán mỹ phẩm của một thương hiệu Việt bị lỗi nút thanh toán sau một lần cập nhật. Quảng cáo vẫn chạy, khách vẫn vào, nhưng đơn về 0 từ 10 giờ sáng đến 4 giờ chiều. Sáng thứ Hai mới có người phát hiện khi xem dashboard.',
  concept:{ name:'Cảnh báo khi số bất thường',
    body:'Dashboard chỉ có ích khi có người nhìn; <b>cảnh báo</b> thì tự tìm đến người cần biết. Cách đặt: chọn vài chỉ số sống còn (đơn hàng, doanh thu, tỉ lệ chuyển đổi, chi phí quảng cáo). Đặt ngưỡng dựa trên mức bình thường: ví dụ đơn theo giờ thấp hơn 50% mức trung bình cùng khung giờ các tuần trước. Mỗi cảnh báo phải có <b>người nhận cụ thể</b> và <b>việc cần làm đầu tiên</b>. Đừng đặt quá nhiều cảnh báo nhạy: khi ngày nào cũng kêu, mọi người sẽ bỏ qua cả cảnh báo thật.' },
  example:'Thương hiệu mỹ phẩm đặt: nếu đơn trong một giờ thấp hơn 50% mức trung bình cùng giờ của bốn tuần trước, gửi tin nhắn cho người trực web và trưởng nhóm quảng cáo. Mức bình thường 11 giờ sáng thứ Bảy là 24 đơn, ngưỡng là 12. Lần sự cố tiếp theo, 11 giờ chỉ có 3 đơn → cảnh báo, 20 phút sau đã sửa. Sáu tiếng mất đơn trước đây, mỗi giờ khoảng 24 đơn, là khoảng 144 đơn bị mất.',
  takeaway:'Mỗi cảnh báo cần ba thứ: ngưỡng dựa trên mức bình thường, người nhận, việc làm đầu tiên.',
  apply:'Chọn một chỉ số sống còn của công ty bạn. Nói trong 60 giây ngưỡng cảnh báo, ai nhận và họ làm gì đầu tiên.',
  mistakes:['Đặt ngưỡng cố định cho mọi giờ, khiến 3 giờ sáng luôn bị báo động giả.','Gửi cảnh báo vào một nhóm chat chung, không ai nhận trách nhiệm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao sự cố 6 tiếng lại không ai biết dù có dashboard?',
    options:[{k:'a',t:'Vì dashboard chỉ được xem đầu tuần, không tự báo'},{k:'b',t:'Vì dashboard không hiển thị được số đơn hàng theo từng giờ'},
             {k:'c',t:'Vì công cụ đo lường không ghi được lỗi thanh toán'},{k:'d',t:'Vì thứ Bảy là ngày ít đơn nên không ai để ý đến số liệu'}],
    answer:'a', why:{a:'Đúng. Dashboard thụ động; cần cảnh báo chủ động.',
      b:'Kể cả có theo giờ, không ai xem thì cũng như không.',
      c:'Không cần ghi lỗi; số đơn về 0 đã là tín hiệu.',
      d:'Thứ Bảy vẫn có đơn; lý do là không có cơ chế báo.'} },
  { type:'mcq', stem:'Bạn được giao đặt cảnh báo cho số đơn. Bạn chọn cách nào?',
    options:[{k:'a',t:'Báo khi đơn trong ngày dưới 100, gửi vào nhóm chat chung của công ty'},{k:'b',t:'Báo khi đơn một giờ dưới 50% mức cùng giờ, gửi người trực web'},
             {k:'c',t:'Báo mỗi khi đơn giờ này ít hơn giờ trước, gửi cho cả phòng marketing'},{k:'d',t:'Không đặt cảnh báo, chỉ yêu cầu mọi người xem dashboard mỗi sáng'}],
    answer:'b', why:{a:'Ngưỡng ngày phát hiện quá muộn; nhóm chung dễ bị ai cũng nghĩ người khác xử lý.',
      b:'Đúng. Ngưỡng theo mức bình thường của giờ đó, và có người nhận cụ thể.',
      c:'Quá nhạy; đơn dao động giờ nào cũng có, sẽ kêu liên tục.',
      d:'Xem mỗi sáng vẫn để lọt sự cố xảy ra buổi chiều cuối tuần.'} },
  { type:'calc', stem:'Mức bình thường lúc 11 giờ sáng thứ Bảy là 24 đơn. Ngưỡng cảnh báo là thấp hơn 50% mức bình thường. Dưới bao nhiêu đơn thì cảnh báo?',
    unit:'đơn', ans:12, tol:0.01, wrong:[[36,'SAI_TINH_TOAN'],[48,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Ngưỡng = 24 × 50%.','= <b>12 đơn</b>.'] },
  { type:'calc', stem:'Sự cố kéo dài 6 giờ, mỗi giờ bình thường khoảng 24 đơn, giá trị đơn trung bình 350.000 đ. Doanh thu ước bị mất là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:50.4, tol:0.1, wrong:[[8.4,'SAI_TINH_TOAN'],[144,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN','NHAM_SO_TUYET_DOI'],
    steps:['Đơn mất = 6 × 24 = 144 đơn.','Doanh thu mất = 144 × 350.000 đ = 50.400.000 đ = <b>50,4 triệu đồng</b>.'] },
  { type:'mcq', stem:'Nhóm đặt 25 cảnh báo, ngày nào cũng kêu vài lần. Sau một tháng, điều gì dễ xảy ra?',
    options:[{k:'a',t:'Nhóm phản ứng nhanh hơn với mọi sự cố nhờ luyện tập'},{k:'b',t:'Dữ liệu chính xác hơn vì được theo dõi thật sát sao'},
             {k:'c',t:'Mọi người quen bỏ qua, kể cả khi cảnh báo thật xảy ra'},{k:'d',t:'Chi phí quảng cáo giảm vì nhóm cắt giảm được lãng phí'}],
    answer:'c', why:{a:'Báo động giả không luyện phản xạ; chúng làm tê liệt.',
      b:'Cảnh báo không làm dữ liệu chính xác hơn.',
      c:'Đúng. Cảnh báo quá nhiều làm mất tác dụng của cảnh báo.',
      d:'Không có liên hệ trực tiếp.'} },
  { type:'mcq', stem:'Chi phí quảng cáo một ngày bỗng gấp ba bình thường nhưng đơn không tăng. Ai nên nhận cảnh báo đầu tiên?',
    options:[{k:'a',t:'Giám đốc, vì đây là chuyện tiền bạc lớn của công ty'},{k:'b',t:'Kế toán, để ghi nhận chi phí cho đúng kỳ báo cáo'},
             {k:'c',t:'Cả công ty qua nhóm chat, để ai rảnh thì vào xem xét'},{k:'d',t:'Người chạy quảng cáo, người có quyền dừng chiến dịch'}],
    answer:'d', why:{a:'Giám đốc cần biết, nhưng không phải người bấm dừng được ngay.',
      b:'Kế toán ghi nhận sau; không ngăn được tiền tiếp tục chảy.',
      c:'Gửi cho tất cả thường có nghĩa là không ai xử lý.',
      d:'Đúng. Cảnh báo phải tới người có thể hành động ngay.'} },
  { type:'mcq', stem:'Vì sao ngưỡng nên dựa trên “cùng khung giờ các tuần trước” thay vì một con số cố định?',
    options:[{k:'a',t:'Vì đơn thay đổi theo giờ và ngày; ngưỡng cố định sẽ báo sai'},{k:'b',t:'Vì con số cố định khó nhớ hơn đối với người trực web'},
             {k:'c',t:'Vì hệ thống không cho phép đặt ngưỡng bằng số cố định'},{k:'d',t:'Vì so với tuần trước luôn cho kết quả đẹp hơn'}],
    answer:'a', why:{a:'Đúng. 3 giờ sáng ít đơn là bình thường; 11 giờ trưa ít đơn mới là bất thường.',
      b:'Khó nhớ không phải vấn đề.',
      c:'Ngưỡng cố định đặt được; chỉ là nó không hợp lý.',
      d:'Mục tiêu là phát hiện đúng, không phải số đẹp.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:dl07-10', skill:'measure', read:'7 phút', t:'Một dashboard cho cả giám đốc lẫn người chạy ads — vì sao không ai hài lòng?',
  situation:'Công ty đồ gia dụng thông minh ở Đà Nẵng dùng chung một dashboard. Giám đốc phàn nàn: “Nhiều số kỹ thuật quá, tôi chỉ cần biết có lãi không”. Người chạy quảng cáo than: “Số theo tuần, tôi cần theo ngày và theo từng nhóm quảng cáo để chỉnh”. Cả hai đều đúng.',
  concept:{ name:'Dashboard theo người đọc',
    body:'Dashboard được thiết kế cho <b>một quyết định của một người</b>. Giám đốc quyết định phân bổ tiền và ưu tiên: cần ít số, nhịp tuần hoặc tháng, nhìn kết quả (doanh thu, lãi gộp sau quảng cáo, chi phí mỗi khách mới) và so với mục tiêu. Người chạy ads quyết định bật, tắt, chỉnh giá thầu: cần nhịp ngày, chi tiết theo chiến dịch và nhóm quảng cáo, các chỉ số dẫn dắt (tỉ lệ bấm, chi phí mỗi bấm, tỉ lệ chuyển đổi). Hai dashboard dùng chung một nguồn số và một định nghĩa, để hai bên không cãi nhau về con số.' },
  example:'Công ty tách làm hai. Dashboard giám đốc có 5 ô theo tuần: doanh thu, chi quảng cáo, lãi gộp sau quảng cáo, số khách mới, chi phí mỗi khách mới. Tuần này: doanh thu 300 triệu, lãi gộp 40% là 120 triệu, chi quảng cáo 45 triệu → lãi sau quảng cáo 75 triệu. Dashboard ads có bảng theo ngày cho 12 nhóm quảng cáo. Hai bên họp 15 phút mỗi tuần dựa trên cùng một bộ số.',
  takeaway:'Hỏi “dashboard này cho ai, để quyết định gì?” trước khi chọn một con số nào.',
  apply:'Nghĩ về hai người trong công ty bạn cần số liệu. Nói trong 60 giây mỗi người cần quyết định gì và vì vậy cần những ô nào.',
  mistakes:['Làm một dashboard “cho tất cả mọi người” và không ai dùng được.','Hai dashboard tính cùng một chỉ số theo hai định nghĩa khác nhau.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao một dashboard chung làm cả giám đốc và người chạy ads không hài lòng?',
    options:[{k:'a',t:'Vì hai người ra quyết định khác nhau, với nhịp khác nhau'},{k:'b',t:'Vì dashboard chưa đủ nhiều chỉ số để thoả mãn tất cả'},
             {k:'c',t:'Vì giám đốc không hiểu các thuật ngữ quảng cáo'},{k:'d',t:'Vì người chạy ads không quan tâm đến lãi của công ty'}],
    answer:'a', why:{a:'Đúng. Mỗi quyết định cần độ chi tiết và nhịp thời gian riêng.',
      b:'Thêm số chỉ làm cả hai khó dùng hơn.',
      c:'Vấn đề không phải thuật ngữ mà là giám đốc không cần những số đó để quyết định.',
      d:'Người chạy ads có quan tâm, nhưng họ cần số chi tiết để chỉnh hằng ngày.'} },
  { type:'mcq', stem:'Bạn thiết kế dashboard cho giám đốc. Bạn chọn gì?',
    options:[{k:'a',t:'Bảng theo ngày cho cả 12 nhóm quảng cáo, kèm tỉ lệ bấm và chi phí mỗi bấm'},{k:'b',t:'Toàn bộ số của người chạy ads, nhưng tô màu xanh đỏ cho giám đốc dễ nhìn hơn'},
             {k:'c',t:'5 ô theo tuần: doanh thu, chi ads, lãi sau ads, khách mới, chi phí mỗi khách mới'},{k:'d',t:'Chỉ ô tổng lượt hiển thị quảng cáo để thấy độ phủ'}],
    answer:'c', why:{a:'Đó là số cho người chỉnh quảng cáo, không phải cho người phân bổ ngân sách.',
      b:'Tô màu không giảm số lượng thứ phải đọc.',
      c:'Đúng. Ít ô, nhịp tuần, tập trung vào kết quả và chi phí.',
      d:'Lượt hiển thị không nói gì về lãi.'} },
  { type:'calc', stem:'Tuần này doanh thu 300 triệu, biên lãi gộp 40%, chi quảng cáo 45 triệu. Lãi gộp sau quảng cáo là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:75, tol:0.1, wrong:[[255,'NHAM_GIA_VON'],[120,'QUEN_TRU_CHI_PHI_QC']], errors:['NHAM_GIA_VON','QUEN_TRU_CHI_PHI_QC'],
    steps:['Lãi gộp = 300 × 40% = 120 triệu.','Trừ quảng cáo: 120 − 45 = <b>75 triệu đồng</b>.'] },
  { type:'mcq', stem:'Người chạy ads cần dashboard để quyết định bật, tắt nhóm quảng cáo mỗi ngày. Nhịp và độ chi tiết nào hợp?',
    options:[{k:'a',t:'Theo tháng, tổng hợp toàn kênh để thấy bức tranh lớn'},{k:'b',t:'Theo quý, so với mục tiêu năm để thấy tiến độ dài hạn'},
             {k:'c',t:'Theo tuần, chỉ riêng doanh thu tổng của cả công ty'},{k:'d',t:'Theo ngày, chi tiết từng chiến dịch và nhóm quảng cáo'}],
    answer:'d', why:{a:'Theo tháng thì phát hiện nhóm tốn tiền quá muộn.',
      b:'Quá chậm cho quyết định hằng ngày.',
      c:'Doanh thu tổng không cho biết nhóm nào cần chỉnh.',
      d:'Đúng. Quyết định hằng ngày cần số hằng ngày ở đúng cấp chiến dịch.'} },
  { type:'mcq', stem:'Dashboard giám đốc ghi 320 đơn, dashboard ads ghi 410 chuyển đổi cùng tuần. Hai bên cãi nhau. Nên làm gì?',
    options:[{k:'a',t:'Tin dashboard ads vì nó được cập nhật thường xuyên hơn'},{k:'b',t:'Thống nhất định nghĩa và ghi rõ nguồn số trên cả hai'},
             {k:'c',t:'Lấy trung bình hai con số làm số chính thức báo cáo'},{k:'d',t:'Bỏ dashboard ads, chỉ giữ một dashboard giám đốc'}],
    answer:'b', why:{a:'Cập nhật thường hơn không có nghĩa là đúng định nghĩa.',
      b:'Đúng. Hai con số có thể đếm hai thứ khác nhau; cần một định nghĩa chung.',
      c:'Trung bình hai số khác định nghĩa không mang nghĩa gì.',
      d:'Người chạy ads vẫn cần số chi tiết để làm việc.'} },
  { type:'mcq', stem:'Trưởng phòng bán hàng cũng muốn một dashboard. Câu hỏi đầu tiên bạn nên hỏi họ?',
    options:[{k:'a',t:'Anh cần những chỉ số nào để đưa vào dashboard?'},{k:'b',t:'Anh muốn dùng màu sắc và kiểu biểu đồ như thế nào?'},
             {k:'c',t:'Mỗi tuần anh cần ra quyết định gì dựa trên số liệu?'},{k:'d',t:'Anh có muốn dùng lại dashboard của giám đốc cho nhanh?'}],
    answer:'c', why:{a:'Người dùng thường liệt kê mọi chỉ số họ biết; bắt đầu từ quyết định sẽ lọc được.',
      b:'Hình thức đến sau nội dung.',
      c:'Đúng. Quyết định quyết định chỉ số, không phải ngược lại.',
      d:'Mỗi vai trò cần số khác nhau; dùng lại là bỏ qua bước hiểu nhu cầu.'} },
  { type:'mcq', stem:'Công ty nhỏ 5 người, một người vừa là chủ vừa chạy ads. Có cần hai dashboard?',
    options:[{k:'a',t:'Có, luôn phải tách hai dashboard dù công ty lớn hay nhỏ'},{k:'b',t:'Không, chỉ cần xem trong trình quản lý quảng cáo là đủ'},
             {k:'c',t:'Có, và thêm dashboard thứ ba cho kế toán để đầy đủ'},{k:'d',t:'Một trang: phần trên cho kết quả tuần, phần dưới cho chi tiết ads'}],
    answer:'d', why:{a:'Nguyên tắc là theo quyết định, không phải theo số lượng dashboard.',
      b:'Trình quản lý quảng cáo không cho thấy lãi và doanh thu từ mọi kênh.',
      c:'Thêm dashboard không ai dùng là lãng phí.',
      d:'Đúng. Hai tầng quyết định vẫn tách bạch, chỉ gộp trên một trang cho gọn.'} }
  ] }

]});
